                        na,nb=a+di,b+dj
                        if 0<=na<h and 0<=nb<w and g[na][nb]==3: st.append((na,nb))
                boxes.append(cc)
    # wall lines: rows/cols with >=2 twos
    wall_rows={i for i in range(h) if sum(g[i][j]==2 for j in range(w))>=2}
    wall_cols={j for j in range(w) if sum(g[i][j]==2 for i in range(h))>=2}
    # box centers and fire axis: if box centers lie on wall cols -> vertical walls -> fire horizontally
    centers=[(min(i for i,j in b)+(max(i for i,j in b)-min(i for i,j in b))/2,
              min(j for i,j in b)+(max(j for i,j in b)-min(j for i,j in b))/2) for b in boxes]
    cx_all={round(c[1]) for _,c in centers}; cy_all={round(c[0]) for c in centers}
    axis='h' if (cx_all and len(cx_all)<=max(w,1) and True) else None
    # decide: fire horizontally if all centers on wall cols or all centers have value 2 at their center
    if any(g[int(r)][int(c)==g[r][int(c)]]==2 for r,c in centers if g[int(round(r))][int(round(c))]==2):
        pass
    def fire_horiz():
        o2=[r[:] for r in o]
        for comp in boxes:
            rs=[i for i,j in comp]; cs=[j for i,j in comp]
            ccy=(min(rs)+max(rs))/2; cxx=(min(cs)+max(cs))/2
            ccy_,cxx_=int(round(ccy)),int(round(cxx))
            owns=set(comp)
            for sgn in (1,-1):
